MOD = 1000000007

def count_edges(n):
    # The number of edges in a complete binary tree of depth n is 2^(n+1) - 2
    return (2 ** (n + 1) - 2) % MOD

def main():
    n, q = map(int, input().split())
    edges = count_edges(n)

    for _ in range(q):
        query = list(map(int, input().split()))
        if query[0] == 1:
            x = query[1]
            if x == 1:
                # Mirror on the right
                edges = (edges * 2 + 1) % MOD
            elif x == 2:
                # Mirror on the left
                edges = (edges * 2 - 1) % MOD
            elif x == 3:
                # Mirror on the top
                edges = (edges * 2 + 2) % MOD
            elif x == 4:
                # Mirror on the bottom
                edges = (edges * 2 - 2) % MOD
        elif query[0] == 2:
            print(edges)

if __name__ == "__main__":
    main()
